whole-agreement.css:
[data-ui-unit="whole-agreement"].consent-all {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding-block: var(--space-3);
  padding-inline: var(--page-inset);
  min-height: 48px;
  width: 100%;
  border-radius: var(--radius);
  background-color: var(--quiet-surface);
  color: var(--text);
  box-sizing: border-box;
}

[data-ui-unit="whole-agreement"] .all-check {
  appearance: auto;
  width: var(--check-size);
  height: var(--check-size);
  margin: 0;
  accent-color: var(--selection);
  flex-shrink: 0;
}

[data-ui-unit="whole-agreement"] .all-label {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.5;
  min-width: 0;
}

[data-ui-unit="whole-agreement"].consent-all:focus-within {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}
